@@ -0,0 +1,181 @@
+(function() {
+  'use strict';
+
+  const STORAGE_KEY = 'l3-021-file-state';
+  let currentFile = null;
+  let originalContent = '';
+  let transformedContent = '';
+
+  function saveState() {
+    if (!currentFile) return;
+    try {
+      const state = {
+        fileName: currentFile.name,
+        fileExtension: currentFile.name.split('.').pop().toLowerCase(),
+        originalContent: originalContent,
+        transformedContent: transformedContent,
+        lastModified: Date.now()
+      };
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
+    } catch (e) {
+      console.warn('Failed to save state:', e);
+    }
+  }
+
+  function loadState() {
+    try {
+      const raw = localStorage.getItem(STORAGE_KEY);
+      if (!raw) return null;
+      return JSON.parse(raw);
+    } catch (e) {
+      console.warn('Failed to load state:', e);
+      return null;
+    }
+  }
+
+  function sanitizeFileName(name) {
+    return name.replace(/[<>:"/\\|?*]/g, '_');
+  }
+
+  function classifyExtension(ext) {
+    const extLower = ext.toLowerCase();
+    if (['txt', 'md', 'log'].includes(extLower)) return 'text';
+    if (['json', 'xml', 'csv'].includes(extLower)) return 'data';
+    if (['html', 'htm', 'css', 'js', 'ts', 'jsx', 'tsx'].includes(extLower)) return 'code';
+    if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(extLower)) return 'image';
+    if (['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'].includes(extLower)) return 'document';
+    if (['zip', 'rar', '7z', 'tar', 'gz'].includes(extLower)) return 'archive';
+    if (['mp3', 'wav', 'ogg', 'flac', 'm4a'].includes(extLower)) return 'audio';
+    if (['mp4', 'webm', 'avi', 'mov', 'mkv'].includes(extLower)) return 'video';
+    return 'other';
+  }
+
+  function transformContent(content, type) {
+    if (!content) return content;
+    
+    switch(type) {
+      case 'uppercase':
+        return content.toUpperCase();
+      case 'lowercase':
+        return content.toLowerCase();
+      case 'reverse':
+        return content.split('').reverse().join('');
+      case 'trim':
+        return content.trim();
+      case 'capitalize':
+        return content.replace(/\b\w/g, c => c.toUpperCase());
+      case 'add-prefix':
+        return '[L3-021] ' + content;
+      case 'add-suffix':
+        return content + ' [END]';
+      default:
+        return content;
+    }
+  }
+
+  function downloadFile(content, filename) {
+    const blob = new Blob([content], { type: 'application/octet-stream' });
+    const url = URL.createObjectURL(blob);
+    const a = document.createElement('a');
+    a.href = url;
+    a.download = sanitizeFileName(filename || 'downloaded-file');
+    document.body.appendChild(a);
+    a.click();
+    document.body.removeChild(a);
+    URL.revokeObjectURL(url);
+  }
+
+  function handleFileSelect(event) {
+    const file = event.target.files[0];
+    if (!file) return;
+
+    currentFile = file;
+    originalContent = file.text().then(content => {
+      transformedContent = content;
+      saveState();
+      updateUI();
+    }).catch(err => {
+      alert('Error reading file: ' + err.message);
+      currentFile = null;
+      document.getElementById('file-status').textContent = 'Error reading file';
+      document.getElementById('file-status').className = 'status-error';
+    });
+  }
+
+  function applyTransformation() {
+    if (!currentFile) return;
+    
+    const type = document.getElementById('transform-type').value;
+    transformedContent = transformContent(originalContent, type);
+    saveState();
+    updateUI();
+  }
+
+  function updateUI() {
+    if (!currentFile) return;
+
+    const ext = currentFile.name.split('.').pop().toLowerCase();
+    const type = classifyExtension(ext);
+    
+    document.getElementById('file-name').textContent = currentFile.name;
+    document.getElementById('file-size').textContent = (currentFile.size / 1024).toFixed(2) + ' KB';
+    document.getElementById('file-type').textContent = type.charAt(0).toUpperCase() + type.slice(1);
+    document.getElementById('file-status').textContent = 'Ready';
+    document.getElementById('file-status').className = 'status-success';
+
+    const preview = document.getElementById('content-preview');
+    if (transformedContent.length > 500) {
+      preview.textContent = transformedContent.substring(0, 500) + '...';
+    } else {
+      preview.textContent = transformedContent;
+    }
+  }
+
+  function resetApp() {
+    currentFile = null;
+    originalContent = '';
+    transformedContent = '';
+    localStorage.removeItem(STORAGE_KEY);
+    document.getElementById('file-name').textContent = 'No file selected';
+    document.getElementById('file-size').textContent = '-';
+    document.getElementById('file-type').textContent = '-';
+    document.getElementById('file-status').textContent = 'Select a file to begin';
+    document.getElementById('file-status').className = '';
+    document.getElementById('content-preview').textContent = '';
+  }
+
+  function init() {
+    const savedState = loadState();
+    if (savedState) {
+      currentFile = {
+        name: savedState.fileName,
+        size: 0,
+        text: () => Promise.resolve(savedState.originalContent)
+      };
+      originalContent = savedState.originalContent;
+      transformedContent = savedState.transformedContent;
+      document.getElementById('file-name').textContent = savedState.fileName;
+      document.getElementById('file-size').textContent = (savedState.originalContent.length / 1024).toFixed(2) + ' KB';
+      document.getElementById('file-type').textContent = classifyExtension(savedState.fileExtension).charAt(0).toUpperCase() + classifyExtension(savedState.fileExtension).slice(1);
+      document.getElementById('file-status').textContent = 'Restored from storage';
+      document.getElementById('file-status').className = 'status-success';
+      const preview = document.getElementById('content-preview');
+      if (savedState.transformedContent.length > 500) {
+        preview.textContent = savedState.transformedContent.substring(0, 500) + '...';
+      } else {
+        preview.textContent = savedState.transformedContent;
+      }
+    }
+
+    document.getElementById('file-input').addEventListener('change', handleFileSelect);
+    document.getElementById('transform-type').addEventListener('change', applyTransformation);
+    document.getElementById('download-btn').addEventListener('click', () => {
+      if (currentFile) {
+        downloadFile(transformedContent, currentFile.name);
+      }
+    });
+    document.getElementById('reset-btn').addEventListener('click', resetApp);
+  }
+
+  init();
+})();

