+
+  function sanitizeFileName(name) {
+    return name.replace(/[<>:"/\\|?*]/g, '_');
+  }
+
+  function classifyExtension(ext) {
+    const extLower = ext.toLowerCase();
+    if (['txt', 'md', 'log'].includes(extLower)) return 'text';
+    if (['json', 'xml', 'csv'].includes(extLower)) return 'data';
+    if (['html', 'htm', 'css', 'js', 'ts', 'jsx', 'tsx'].includes(extLower)) return 'code';
+    if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(extLower)) return 'image';
+    if (['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'].includes(extLower)) return 'document';
+    if (['zip', 'rar', '7z', 'tar', 'gz'].includes(extLower)) return 'archive';
+    if (['mp3', 'wav', 'ogg', 'flac', 'm4a'].includes(extLower)) return 'audio';
+    if (['mp4', 'webm', 'avi', 'mov', 'mkv'].includes(extLower)) return 'video';
+    return 'other';
+  }
+
+  function transformContent(content, type) {
+    if (!content) return content;
+    
+    switch(type) {
+      case 'uppercase':
+        return content.toUpperCase();
+      case 'lowercase':
+        return content.toLowerCase();
+      case 'reverse':
+        return content.split('').reverse().join('');
+      case 'trim':
+        return content.trim();
+      case 'capitalize':
+        return content.replace(/\b\w/g, c => c.toUpperCase());
+      case 'add-prefix':
+        return '[L3-021] ' + content;
+      case 'add-suffix':
+        return content + ' [END]';
+      default:
+        return content;
+    }
+  }
+
+  function downloadFile(content, filename) {
+    const blob = new Blob([content], { type: 'application/octet-stream' });
+    const url = URL.createObjectURL(blob);
+    const a = document.createElement('a');
+    a.href = url;
+    a.download = sanitizeFileName(filename || 'downloaded-file');
+    document.body.appendChild(a);
+    a.click();
+    document.body.removeChild(a);
+    URL.revokeObjectURL(url);
+  }
+
+  function handleFileSelect(event) {
+    const file = event.target.files[0];
+    if (!file) return;
+
+    currentFile = file;
+    originalContent = file.text().then(content => {
+      transformedContent = content;
+      saveState();
+      updateUI();
