+    
+    document.getElementById('file-name').textContent = currentFile.name;
+    document.getElementById('file-size').textContent = (currentFile.size / 1024).toFixed(2) + ' KB';
+    document.getElementById('file-type').textContent = type.charAt(0).toUpperCase() + type.slice(1);
