+      currentFile = {
+        name: savedState.fileName,
+        size: 0,
+        text: () => Promise.resolve(savedState.originalContent)
+      };
+      originalContent = savedState.originalContent;
+      transformedContent = savedState.transformedContent;
+      document.getElementById('file-name').textContent = savedState.fileName;
+      document.getElementById('file-size').textContent = (savedState.originalContent.length / 1024).toFixed(2) + ' KB';
+      document.getElementById('file-type').textContent = classifyExtension(savedState.fileExtension).charAt(0).toUpperCase() + classifyExtension(savedState.fileExtension).slice(1);
+      document.getElementById('file-status').textContent = 'Restored from storage';
+      document.getElementById('file-status').className = 'status-success';
+      const preview = document.getElementById('content-preview');
+      if (savedState.transformedContent.length > 500) {
+        preview.textContent = savedState.transformedContent.substring(0, 500) + '...';
